from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Ssh_status(EmssimCommand):
    def __init__(self, method='ssh_status', timeout=60, rpc_connection_name='localRPC'):
        super(Ssh_status, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Ssh_status, self).on_new_data(**data)
        if 'msg' in data:
            if data['msg'] == 'ssh_info':
                self._ret['ssh_status'] = data['status']
                self._ret['details'] = data['details']
                if (data['status'] == 'Enabled') and (len(self._ret['details']) > 5):
                    self._ret[data['details'][2]] = data['details'][3]
                    self._ret[data['details'][4]] = data['details'][5]
        elif 'status' in data:
            self._ret['status'] = data['status']
